// src/pages/DeliveryDashboardPage.tsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";

interface Delivery {
  _id: string;
  customerId: string;
  driverId: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

export default function DeliveryDashboardPage() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    axios
      .get<Delivery[]>("http://localhost:5000/api/delivery")
      .then((res) => setDeliveries(res.data))
      .catch(() => alert("❌ Failed to fetch deliveries"));
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm("Are you sure you want to delete this delivery?")) return;
    try {
      await axios.delete(`http://localhost:5000/api/delivery/${id}`);
      setDeliveries((prev) => prev.filter((d) => d._id !== id));
    } catch {
      alert("❌ Failed to delete delivery");
    }
  };

  const filtered = deliveries.filter(
    (d) =>
      d.customerId.toLowerCase().includes(searchQuery.toLowerCase()) ||
      d.status.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div style={container}>
      <header style={headerFooter}>
        <button type="button" style={btn} onClick={() => navigate("/delivery/new")}>
          + New Delivery
        </button>
        <button type="button" style={btn} onClick={() => navigate("/driver/new")}>
          + Add Driver
        </button>
        <button type="button" style={btn} onClick={() => navigate("/drivers")}>
          View Drivers
        </button>
        <button type="button" style={btn} onClick={() => navigate("/analytics")}>
          📈 Analytics
        </button>
      </header>

      <main style={main}>
        <div style={{ marginBottom: 16 }}>
          <input
            type="text"
            placeholder="Search by Customer or Status"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={searchInput}
          />
        </div>

        <table style={table}>
          <thead>
            <tr>
              <th style={th}>Customer ID</th>
              <th style={th}>Status</th>
              <th style={th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((d) => (
              <tr key={d._id}>
                <td style={td}>{d.customerId}</td>
                <td style={td}>{d.status}</td>
                <td style={td}>
                  <button
                    type="button"
                    style={actionBtn}
                    onClick={() => navigate(`/delivery/${d._id}`)}
                  >
                    View
                  </button>
                  <button
                    type="button"
                    style={editBtn}
                    onClick={() => navigate(`/edit-delivery/${d._id}`)}
                  >
                    Edit
                  </button>
                  <button
                    type="button"
                    style={deleteBtn}
                    onClick={() => handleDelete(d._id)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </main>

      <footer style={headerFooter}>
        <span>© 2025 Delivery Dashboard</span>
        <button
          type="button"
          style={{ ...btn, marginLeft: "auto" }}
          onClick={() => navigate("/drivers")}
        >
          View Drivers
        </button>
      </footer>
    </div>
  );
}

// layout
const container: React.CSSProperties = {
  display: "flex",
  flexDirection: "column",
  minHeight: "100vh",
};

const headerFooter: React.CSSProperties = {
  background: "#e0f7fa",
  padding: "12px 20px",
  display: "flex",
  alignItems: "center",
  gap: "10px",
};

// main content
const main: React.CSSProperties = {
  flex: 1,
  padding: "20px",
  background: "#fafafa",
};

// table styling
const table: React.CSSProperties = {
  width: "100%",
  borderCollapse: "collapse",
};
const th: React.CSSProperties = {
  borderBottom: "2px solid #bbb",
  padding: "8px",
  textAlign: "left",
};
const td: React.CSSProperties = {
  borderBottom: "1px solid #ddd",
  padding: "8px",
};

// inputs & buttons
const searchInput: React.CSSProperties = {
  width: "100%",
  padding: "8px",
  borderRadius: 4,
  border: "1px solid #ccc",
};

const btn: React.CSSProperties = {
  padding: "8px 16px",
  background: "#0288d1",
  color: "#fff",
  border: "none",
  borderRadius: 4,
  cursor: "pointer",
};

const actionBtn: React.CSSProperties = {
  ...btn,
  marginRight: 6,
  padding: "4px 8px",
  fontSize: "0.9em",
};

const editBtn: React.CSSProperties = {
  ...actionBtn,
  background: "#ffc107",
  color: "#000",
};

const deleteBtn: React.CSSProperties = {
  ...actionBtn,
  background: "#dc3545",
};
